import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds to nearest cent', () => {
  assert.equal(roundCents(100.4), 100);
  assert.equal(roundCents(100.5), 100);
  assert.equal(roundCents(100.6), 101);
});

test('formatEuros formats euros', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(50), '€0.50');
  assert.equal(formatEuros(0), '€0.00');
});

test('parseEuros parses euro strings', () => {
  assert.equal(parseEuros('12').value, 1200);
  assert.equal(parseEuros('12.5').value, 1250);
  assert.equal(parseEuros('1,234.56').value, 123456);
});

test('RATES includes EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const r = convert(100000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, 100000);
});

test('convert EUR to USD applies exchange rate', () => {
  const r = convert(100, 'EUR');
  assert.equal(r.ok, true);
  const expected = roundCents(100 * 1.085);
  assert.equal(r.value, expected);
});

test('convert EUR to GBP applies exchange rate', () => {
  const r = convert(100, 'GBP');
  assert.equal(r.ok, true);
  const expected = roundCents(100 * 0.8425);
  assert.equal(r.value, expected);
});

test('convert with unknown currency fails', () => {
  const r = convert(100, 'JPY');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_CURRENCY');
});

test('convert with large amount', () => {
  const r = convert(123456, 'USD');
  assert.equal(r.ok, true);
  const expected = roundCents(123456 * 1.085);
  assert.equal(r.value, expected);
});

test('convert negative amount', () => {
  const r = convert(-100, 'USD');
  assert.equal(r.ok, true);
  const expected = roundCents(-100 * 1.085);
  assert.equal(r.value, expected);
});

test('convert with rounding', () => {
  const r = convert(1, 'USD');
  assert.equal(r.ok, true);
  const expected = roundCents(1 * 1.085);
  assert.equal(r.value, expected);
  assert(Number.isInteger(r.value));
});

test('formatMoney formats EUR', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney formats USD', () => {
  assert.equal(formatMoney(100000, 'USD'), '$1,085.00');
});

test('formatMoney formats GBP', () => {
  assert.equal(formatMoney(100000, 'GBP'), '£84.25');
});

test('formatMoney defaults to EUR', () => {
  assert.equal(formatMoney(123456), '€1,234.56');
});

test('formatMoney formats zero', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
});

test('formatMoney formats small amounts', () => {
  assert.equal(formatMoney(1, 'EUR'), '€0.01');
  assert.equal(formatMoney(50, 'EUR'), '€0.50');
  assert.equal(formatMoney(99, 'EUR'), '€0.99');
});

test('formatMoney formats with thousands separator', () => {
  assert.equal(formatMoney(1234567, 'EUR'), '€12,345.67');
  assert.equal(formatMoney(1000000, 'USD'), '$10,850.00');
});

test('formatMoney formats negative EUR', () => {
  assert.equal(formatMoney(-123456, 'EUR'), '-€1,234.56');
});

test('formatMoney formats negative USD', () => {
  assert.equal(formatMoney(-100000, 'USD'), '-$1,085.00');
});

test('formatMoney with unknown currency', () => {
  const result = formatMoney(100, 'JPY');
  assert.equal(result, 'Unknown currency');
});

test('formatMoney converts EUR cents to target currency', () => {
  const eurCents = 100000;
  const usdFormatted = formatMoney(eurCents, 'USD');
  const expectedCents = roundCents(eurCents * 1.085);
  const expectedFormatted = `$${Math.floor(expectedCents / 100)}.${String(expectedCents % 100).padStart(2, '0')}`;
  assert(usdFormatted.includes(expectedFormatted.slice(1)));
});

